PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY, name TEXT NOT NULL, sha256 TEXT NOT NULL UNIQUE, html BLOB NOT NULL, imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS originals(id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL REFERENCES sources(id), row_number INTEGER NOT NULL, cells_json TEXT NOT NULL, row_html TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards(id INTEGER PRIMARY KEY, word TEXT NOT NULL UNIQUE COLLATE NOCASE, type TEXT NOT NULL, pronunciation TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id INTEGER PRIMARY KEY, created_at REAL NOT NULL, completed_at REAL, turn INTEGER NOT NULL DEFAULT 0, last_card INTEGER, last_at REAL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_batch ON batches((1)) WHERE completed_at IS NULL;
CREATE TABLE IF NOT EXISTS members(batch_id INTEGER NOT NULL REFERENCES batches(id), card_id INTEGER NOT NULL REFERENCES cards(id), streak INTEGER NOT NULL DEFAULT 0 CHECK(streak BETWEEN 0 AND 3), ready INTEGER NOT NULL DEFAULT 0, due_turn INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL, PRIMARY KEY(batch_id,card_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_batch_per_word ON members(card_id);
CREATE TABLE IF NOT EXISTS schedules(card_id INTEGER PRIMARY KEY REFERENCES cards(id), state TEXT NOT NULL, due REAL NOT NULL, last_rating TEXT, reviews INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, card_id INTEGER NOT NULL REFERENCES cards(id), mode TEXT NOT NULL CHECK(mode IN ('learn','review')), rating TEXT NOT NULL, created_at REAL NOT NULL, early INTEGER NOT NULL DEFAULT 0, fsrs_log TEXT);
CREATE TABLE IF NOT EXISTS presentation(id INTEGER PRIMARY KEY CHECK(id=1), token TEXT NOT NULL, card_id INTEGER NOT NULL REFERENCES cards(id), mode TEXT NOT NULL, revealed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS actions(id INTEGER PRIMARY KEY, token TEXT UNIQUE NOT NULL, snapshot TEXT NOT NULL, undone INTEGER NOT NULL DEFAULT 0);
